using Azure.Search.Documents;using Azure.Search.Documents.Models;using Azure.Messaging.ServiceBus;using EnterpriseDocumentIntelligence.BuildingBlocks.Infrastructure;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;using System.Text.Json;
public sealed class ServiceBusClientFactory(IConfiguration c){readonly ServiceBusClient client=!string.IsNullOrWhiteSpace(c["ServiceBus:ConnectionString"])?new(c["ServiceBus:ConnectionString"]!):new(c["ServiceBus:FullyQualifiedNamespace"]!,new Azure.Identity.DefaultAzureCredential());public ServiceBusProcessor Create(string t,string s)=>client.CreateProcessor(t,s,new ServiceBusProcessorOptions{MaxConcurrentCalls=8,PrefetchCount=50,AutoCompleteMessages=false});}
public sealed class Worker(ServiceBusClientFactory factory,SearchClient index,ILogger<Worker> log):BackgroundService{protected override async Task ExecuteAsync(CancellationToken ct){var p=factory.Create(Topics.EmbeddingEvents,"indexing-sub");p.ProcessMessageAsync+=Handle;p.ProcessErrorAsync+=Error;await p.StartProcessingAsync(ct);try{await Task.Delay(Timeout.Infinite,ct);}catch(OperationCanceledException){}finally{await p.StopProcessingAsync();await p.DisposeAsync();}}async Task Handle(ProcessMessageEventArgs a){try{var m=JsonSerializer.Deserialize<EmbeddingsCreated>(a.Message.Body.ToString(),new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid embeddings event");var batch=new IndexDocumentsBatch<SearchDocument>();foreach(var c in m.Chunks)batch.Actions.Add(IndexDocumentsAction.Upload(new SearchDocument{{"id",c.ChunkId.ToString()},{"TenantId",m.TenantId.ToString()},{"DocumentId",m.DocumentId.ToString()},{"Text",c.Text},{"Citation",$"document:{m.DocumentId}/version:{m.VersionId}/chunk:{c.Number}"},{"ContentVector",c.Embedding}}));await index.IndexDocumentsAsync(batch,cancellationToken:a.CancellationToken);log.LogInformation("Indexed {Count} chunks Document={DocumentId}",m.Chunks.Count,m.DocumentId);await a.CompleteMessageAsync(a.Message);}catch(Exception ex){log.LogError(ex,"Indexing failed");if(a.Message.DeliveryCount>=5)await a.DeadLetterMessageAsync(a.Message,"max-delivery",ex.Message);else await a.AbandonMessageAsync(a.Message);}}Task Error(ProcessErrorEventArgs e){log.LogError(e.Exception,"Indexing Service Bus error");return Task.CompletedTask;}}